// ==================== 订单模块常量 ====================

/** 订单状态配置 */
export interface OrderStatusConfig {
  text: string
  color: string
  status: string
}

/** 订单状态基础配置 */
export const ORDER_STATUS_CONFIG: Record<number, OrderStatusConfig> = {
  1: { text: '待支付', color: '#FAAD14', status: 'warning' },
  2: { text: '待取件', color: '#1890FF', status: 'processing' },
  3: { text: '已取件', color: '#52C41A', status: 'success' },
  4: { text: '已取消', color: '#8C8C8C', status: 'default' },
  5: { text: '已超时', color: '#FF4D4F', status: 'error' },
  6: { text: '滞留', color: '#FF4D4F', status: 'error' },
}

/** 状态首字母大写转换 */
export function capitalize(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1)
}

/** 订单状态映射（用于组件内显示） */
export const ORDER_STATUS_MAP: Record<number, OrderStatusConfig> = ORDER_STATUS_CONFIG

/** Ant Design Badge 有效的状态值 */
type BadgeStatus = 'success' | 'error' | 'warning' | 'default' | 'processing'

/** 订单状态 ProTable valueEnum 格式 */
export const ORDER_STATUS_VALUE_ENUM: Record<string, { text: string; status: BadgeStatus }> =
  Object.entries(ORDER_STATUS_CONFIG).reduce((acc, [key, value]) => {
    acc[key] = {
      text: value.text,
      status: value.status as BadgeStatus,
    }
    return acc
  }, {} as Record<string, { text: string; status: BadgeStatus }>)

